/**
 * draw.io palette data (General, Misc, Advanced, Basic, Arrows, Flowchart) pinned to
 * jgraph/drawio v32.4.1. Data is generated by scripts/drawio-palettes/extract-palettes.ts.
 *
 * getBasenameForStencil is ported from jgraph/drawio v32.4.1
 * src/main/webapp/js/grapheditor/Graph.js:22346 (mxStencilRegistry.getBasenameForStencil).
 * Copyright (c) 2006-2025, JGraph Holdings Ltd / draw.io AG. Licensed under Apache-2.0.
 */
import type { DrawioPaletteId, PaletteDef, PaletteMeta } from './types';

export type { DrawioPaletteId, PaletteDef, PaletteEntry, PaletteEntryClass, PaletteMeta } from './types';

export const DRAWIO_TAG = 'v32.4.1';

/** Palettes in draw.io sidebar order; the legacy stencil-based Arrows palette is hidden by default. */
export const PALETTES: readonly PaletteMeta[] = [
  { id: 'general', title: 'General', defaultVisible: true },
  { id: 'misc', title: 'Misc', defaultVisible: true },
  { id: 'advanced', title: 'Advanced', defaultVisible: true },
  { id: 'basic', title: 'Basic', defaultVisible: true },
  { id: 'arrows2', title: 'Arrows', defaultVisible: true },
  { id: 'flowchart', title: 'Flowchart', defaultVisible: true },
  { id: 'arrows', title: 'Arrows (legacy)', defaultVisible: false },
];

/**
 * Stencil files (basenames under public/stencils/, without .xml) each palette needs, i.e.
 * getBasenameForStencil() of every stencil-rendered (cls 'b') shape name in the palette.
 * Kept static so callers can preload before the palette JSON is loaded; the unit test
 * checks it against the generated data.
 */
const STENCIL_BASENAMES: Record<DrawioPaletteId, readonly string[]> = {
  general: [],
  misc: [],
  advanced: [],
  basic: ['basic'],
  arrows2: [],
  flowchart: ['flowchart'],
  arrows: ['arrows'],
};

const LOADERS: Record<DrawioPaletteId, () => Promise<{ default: unknown }>> = {
  general: () => import('./data/general.json'),
  misc: () => import('./data/misc.json'),
  advanced: () => import('./data/advanced.json'),
  basic: () => import('./data/basic.json'),
  arrows2: () => import('./data/arrows2.json'),
  flowchart: () => import('./data/flowchart.json'),
  arrows: () => import('./data/arrows.json'),
};

export function isDrawioPaletteId(id: string): id is DrawioPaletteId {
  return Object.prototype.hasOwnProperty.call(LOADERS, id);
}

const cache = new Map<DrawioPaletteId, Promise<PaletteDef>>();

/** Loads a palette's data (code-split JSON chunk). Rejects for unknown ids. */
export function loadPalette(id: string): Promise<PaletteDef> {
  if (!isDrawioPaletteId(id)) return Promise.reject(new Error(`Unknown draw.io palette: ${id}`));
  let p = cache.get(id);
  if (!p) {
    p = LOADERS[id]().then((m) => m.default as PaletteDef);
    p.catch(() => cache.delete(id));
    cache.set(id, p);
  }
  return p;
}

/** Stencil basenames to preload (e.g. ['basic'] -> `${BASE_URL}stencils/basic.xml`) before rendering the palette. */
export function paletteStencilBasenames(id: string): string[] {
  return isDrawioPaletteId(id) ? [...STENCIL_BASENAMES[id]] : [];
}

/**
 * mxStencilRegistry.getBasenameForStencil: 'mxgraph.mscae.enterprise.x' -> 'mscae/enterprise',
 * 'mxgraph.basic.x' -> 'basic'; null when the name is not an mxgraph.* stencil.
 * draw.io loads `stencils/<basename with '_-_' replaced by '_'>.xml` for it.
 */
export function getBasenameForStencil(name: string | null | undefined): string | null {
  let tmp: string | null = null;
  if (name != null && typeof name === 'string') {
    const parts = name.split('.');
    if (parts.length > 0 && parts[0] === 'mxgraph') {
      tmp = parts[1];
      for (let i = 2; i < parts.length - 1; i++) tmp += '/' + parts[i];
    }
  }
  return tmp ?? null;
}

/** Unique stencil file basenames (with draw.io's '_-_' -> '_' rule applied) for the given shape names. */
export function stencilBasenamesForShapes(shapeNames: Iterable<string>): string[] {
  const out: string[] = [];
  for (const name of shapeNames) {
    const b = getBasenameForStencil(name);
    if (b == null) continue;
    const file = b.replace('_-_', '_');
    if (!out.includes(file)) out.push(file);
  }
  return out;
}
